using GraphApi.Models.USR.Parientes;namespace GraphApi.Services.USR.Parientes{    /// <summary>    /// Define las operaciones de negocio y persistencia para Parientes.    /// </summary>    public interface IParientesService    {        /// <summary>        /// Obtiene la lista de Parientes con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadParientes>> GetParientes(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Parientes con filtros opcionales.        /// </summary>        /// <param name="parienteID">Filtro opcional para ParienteID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="nombreUsuario">Filtro opcional para NombreUsuario.</param>        /// <param name="correoUsuario">Filtro opcional para CorreoUsuario.</param>        /// <param name="nombrePariente">Filtro opcional para NombrePariente.</param>        /// <param name="parentescoID">Filtro opcional para ParentescoID.</param>        /// <param name="parentesco">Filtro opcional para Parentesco.</param>        /// <param name="telefonoPariente">Filtro opcional para TelefonoPariente.</param>        /// <param name="correoPariente">Filtro opcional para CorreoPariente.</param>        /// <param name="esContactoEmergencia">Filtro opcional para EsContactoEmergencia.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetParientesDynamic(            int? parienteID,            int? usuarioID,            string? nombreUsuario,            string? correoUsuario,            string? nombrePariente,            int? parentescoID,            string? parentesco,            string? telefonoPariente,            string? correoPariente,            bool? esContactoEmergencia,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Pariente.        /// </summary>        /// <param name="objInput">Datos para crear el Pariente.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadParientes> CreateParientes(            clCreateParientes objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Pariente.        /// </summary>        /// <param name="objInput">Datos para actualizar el Pariente, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadParientes?> UpdateParientes(            clUpdateParientes objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Pariente por su ID.        /// </summary>        /// <param name="nParientesID">ID del Pariente a eliminar.</param>        Task<bool> DeleteParientes(int nParientesID);    }}